import numpy as np, torch, model
torch.manual_seed(0); np.random.seed(0)
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c0_blocks.1_k8.npy')); b=-8.3501
def dec(xi,c,delta,lo=0,hi=9):
    x=torch.tensor(xi,dtype=torch.float32); c=torch.tensor(c,dtype=torch.float32)
    fire=torch.zeros(len(xi)); d=None if delta is None else torch.tensor(delta,dtype=torch.float32)
    with torch.no_grad():
        for k in range(20):
            t=torch.full((x.shape[0],),1-k/20)
            v,A=net.velocity(x,t,c,("blocks.1",),count=False)
            if d is not None and lo<=k<hi:
                f=(A["blocks.1"]@w+b>0).float(); fire+=f; v=v+f[:,None]*d
            x=x-v/20
    return x.numpy(), (fire>0).numpy()
n=len(neg['uid']); NS=256
xi=np.random.randn(n*NS,2).astype(np.float32); cs=np.repeat(neg['c'],NS).astype(np.float32)
base,_=dec(xi,cs,None)
def resid(a): return np.mean([np.mean(model.in_basin(i,a[i*NS:(i+1)*NS])) for i in range(n)])
print('base resid',resid(base))
cg=np.random.rand(4096).astype(np.float32); xg=np.random.randn(4096,2).astype(np.float32)
bg,_=dec(xg,cg,None)
def atyp(a,c):
    return np.array([np.sqrt(((bg[np.abs(cg-c[j])<0.03]-a[j])**2).sum(-1)).min() for j in range(len(a))])
print('base atyp', np.median(atyp(bg[:200]+0.0,cg[:200])))
for hi in [9,12]:
  for ang in range(0,360,45):
    for mag in [2,4,8]:
        dv=-mag*np.array([np.cos(np.radians(ang)),np.sin(np.radians(ang))])
        a,f=dec(xi,cs,dv,0,hi); ag,fg=dec(xg,cg,dv,0,hi)
        mv=np.linalg.norm(ag-bg,axis=1)>0.1
        at=atyp(ag[mv],cg[mv]) if mv.any() else np.zeros(1)
        print(hi,ang,mag,'resid %.3f'%resid(a),'firegen %.3f moved %.3f atyp_med %.3f atyp90 %.3f'%(fg.mean(),mv.mean(),np.median(at),np.quantile(at,.9)),flush=True)

import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c1_blocks.2.act_k12.npy')).float(); b=-14.1689
xi=torch.tensor(np.load('sim_xi.npy')); c=torch.tensor(np.load('sim_c.npy')); a0=np.load('sim_a0.npy'); lab=np.load('sim_lab.npy')
cn=c.numpy()
def knn(a):
    out=np.zeros(len(a),bool); dist=np.zeros(len(a))
    for i in range(len(a)):
        m=np.abs(cn-cn[i])<0.05
        dd=np.linalg.norm(a0[m]-a[i],axis=1); j=np.argmin(dd); out[i]=lab[m][j]; dist[i]=dd[j]
    return out,dist
def run(u,alpha,klo,khi,r=0.5,thr=0.0):
    x=xi.clone()
    dv=-20*alpha*r*torch.tensor(u).float()/(khi-klo)
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,A=net.velocity(x,t,c,("blocks.2.act",),count=False)
        if klo<=k<khi:
            f=(A["blocks.2.act"]@w+b)>thr
            v=v+f[:,None].float()*dv
        x=x-v/20
    return x.numpy()
best=None
for J in [5,6]:
 for alpha in [3,4,5]:
  for (lo,hi) in [(10,13),(8,13),(6,13),(10,15)]:
    ang=J*np.pi/4; u=[np.cos(ang),np.sin(ang)]
    a=run(u,alpha,lo,hi); l,dist=knn(a)
    moved=np.linalg.norm(a-a0,axis=1)>0.3
    print(J,alpha,lo,hi,'bad',l.mean().round(3),'off',(dist>0.3).mean().round(4),'movednonlab',(moved&~lab).mean().round(4), 'land', np.round(a[lab&~l].mean(0),2) if (lab&~l).any() else '')
